import os
import base64
import mimetypes
from typing import Optional

from openai import OpenAI


def _image_to_data_url(image_path: str) -> str:
    mime_type, _ = mimetypes.guess_type(image_path)
    if mime_type is None:
        mime_type = "image/jpeg"
    with open(image_path, "rb") as f:
        encoded = base64.b64encode(f.read()).decode("utf-8")
    return f"data:{mime_type};base64,{encoded}"


def generate_visual_description(image_path: str, max_words: int = 25) -> str:
    """
    Generate a short visual description of an image using OpenAI's hosted vision-capable API.
    Requires OPENAI_API_KEY in the environment.
    """
    client = OpenAI()

    data_url = _image_to_data_url(image_path)
    prompt = (
        f"Write a short visual description of this image in at most {max_words} words. "
        "Be concise and factual."
    )

    response = client.responses.create(
        model="gpt-4o-mini",
        input=[
            {
                "role": "user",
                "content": [
                    {"type": "input_text", "text": prompt},
                    {"type": "input_image", "image_url": data_url},
                ],
            }
        ],
    )

    text = getattr(response, "output_text", None)
    if text:
        return text.strip()

    # Fallback parsing for SDK response structure variations
    parts = []
    for item in getattr(response, "output", []) or []:
        for content in getattr(item, "content", []) or []:
            text_part = getattr(content, "text", None)
            if text_part:
                parts.append(text_part)
    return " ".join(parts).strip() if parts else ""
